use crate::aap::caps::kb_read;

struct Node;

/// Upper bound on the question length, from the node's contract.
const MAX_QUESTION_CHARS: usize = 512;

/// Used only when the knowledge base returns nothing for the question or
/// any of its entities, so that `knowledge` is always present.
const NO_KNOWLEDGE: &str = "No knowledge-base entries matched this query.";

fn bound_question(question: String) -> String {
    if question.chars().count() <= MAX_QUESTION_CHARS {
        question
    } else {
        question.chars().take(MAX_QUESTION_CHARS).collect()
    }
}

fn push_unique(knowledge: &mut Vec<String>, entries: Vec<String>) {
    for entry in entries {
        if entry.trim().is_empty() {
            continue;
        }
        if !knowledge.iter().any(|k| *k == entry) {
            knowledge.push(entry);
        }
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;
        let intent = inner.intent;
        let question = bound_question(inner.question);

        let mut knowledge: Vec<String> = Vec::new();

        // Primary lookup: the question itself.
        push_unique(&mut knowledge, kb_read::lookup(&question));

        // Fallback: look up by the extracted entities if the question found nothing.
        if knowledge.is_empty() {
            for entity in inner.entities.iter() {
                if entity.trim().is_empty() {
                    continue;
                }
                push_unique(&mut knowledge, kb_read::lookup(entity));
            }
        }

        if knowledge.is_empty() {
            knowledge.push(String::from(NO_KNOWLEDGE));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
